cd /workspace && python3 - <<'PY'
import json
p=json.load(open('contracts/openapi.contract.json'))
print('OPERATIONS')
for path,item in p['paths'].items():
 for method,op in item.items():
  if method.startswith('x'): continue
  rb=op.get('requestBody',{}).get('content',{}).get('application/json',{}).get('schema',{})
  def fields(s):
   if '$ref' in s:return s['$ref']
   return ','.join(s.get('required',[]))
  print(method.upper(),path,op.get('operationId'),'body=',fields(rb),'responses=',','.join(op.get('responses',{})))
print('\nSCHEMAS')
for n,s in p.get('components',{}).get('schemas',{}).items():
 print(n, 'required=',s.get('required',[]), 'props=',','.join(s.get('properties',{})))
PY

