action.command:
cd /workspace && python3 - <<'PY'
import json
p=json.load(open('contracts/openapi.contract.json'))
for path,item in p['paths'].items():
 for m,op in item.items():
  if m.startswith('x'): continue
  rb=op.get('requestBody',{}).get('content',{}).get('application/json',{}).get('schema',{})
  def desc(s):
   if '$ref' in s:return s['$ref']
   if s.get('type')=='object': return '{'+','.join(f"{k}{'*' if k in s.get('required',[]) else ''}" for k in s.get('properties',{}))+'}'
   return str(s)
  good=next((v for k,v in op.get('responses',{}).items() if k.startswith('2')),None)
  rs=good.get('content',{}).get('application/json',{}).get('schema',{}) if good else {}
  print(f"{op['operationId']} | {m.upper()} {path} | params={','.join(x['name'] for x in op.get('parameters',[]))} | body={desc(rb)} | response={desc(rs)}")
PY

