package main

import("crypto/sha256";"encoding/hex";"encoding/json";"fmt";"net/http";"os";"path/filepath";"strings";"sync";"time")
type User struct{ID,Username,Password string; Roles,Qualifications []string; Active,ActiveRole string}
type SampleType struct{ID,Name,ContainerType string; TemperatureMinC,TemperatureMaxC float64; QualifiedCollectorRequired bool; RequiredQualification string; IncompatibleSampleTypes []string; RequiresCooledRoute,BatchingAllowed bool}
type Sample struct{ID,RequestID,RequesterID,SampleTypeID,Status,OriginType,ContainerType,RequestedAt,DeliveryDeadline,JourneyID string; Origin map[string]interface{}; TemperatureMinC,TemperatureMaxC float64; Timeline []map[string]interface{}; LocationStale bool; Exception string}
type State struct{Users map[string]User; Types map[string]SampleType; Samples map[string]Sample; Audits []map[string]interface{}; Version int}
var mu sync.Mutex;var st State;var sessions=map[string]string{};var db="data/state.json"
func uid()string{b:=make([]byte,16);for i:=range b{b[i]=byte(time.Now().UnixNano()>>uint(i%8))};return fmt.Sprintf("%x-%x-%x-%x-%x",b[:4],b[4:6],b[6:8],b[8:10],b[10:])}
func now()string{return time.Now().UTC().Format(time.RFC3339)}
func hash(x string)string{b:=sha256.Sum256([]byte(x));return hex.EncodeToString(b[:])}
func save(){os.MkdirAll(filepath.Dir(db),0755);b,_:=json.MarshalIndent(st,"","  ");_ = os.WriteFile(db,b,0644)}
func load(){b,e:=os.ReadFile(db);if e==nil{_ = json.Unmarshal(b,&st)};if st.Users==nil{st.Users=map[string]User{}};if st.Types==nil{st.Types=map[string]SampleType{}};if st.Samples==nil{st.Samples=map[string]Sample{}};if len(st.Users)==0{u:=User{ID:uid(),Username:os.Getenv("ADMIN_USERNAME"),Password:hash(os.Getenv("ADMIN_PASSWORD")),Roles:[]string{"administrator","dispatcher"},Active:"true"};if u.Username==""{u.Username="admin"};if os.Getenv("ADMIN_PASSWORD")==""{u.Password=hash("admin")};st.Users[u.ID]=u};if len(st.Types)==0{for _,n:=range []string{"Amber","Indigo","Frost","Pulse"}{x:=SampleType{ID:uid(),Name:n,ContainerType:"standard",TemperatureMinC:15,TemperatureMaxC:25,QualifiedCollectorRequired:true,RequiredQualification:strings.ToUpper(n),BatchingAllowed:n!="Pulse"};if n=="Frost"{x.ContainerType="cooled";x.TemperatureMinC=2;x.TemperatureMaxC=8;x.RequiresCooledRoute=true};if n=="Indigo"{x.IncompatibleSampleTypes=[]string{"Amber"}};st.Types[x.ID]=x}};save()}
func write(w http.ResponseWriter,status int,v interface{}){w.Header().Set("Content-Type","application/json");w.WriteHeader(status);_ = json.NewEncoder(w).Encode(v)}
func fail(w http.ResponseWriter,s,c,m string){write(w,atoi(s),map[string]string{"error":m,"code":c})};func atoi(s string)int{if s=="401"{return 401};if s=="403"{return 403};if s=="404"{return 404};return 400}
func read(r *http.Request)map[string]interface{}{v:=map[string]interface{}{};_ = json.NewDecoder(r.Body).Decode(&v);return v}
func actor(r *http.Request)(User,bool){u,ok:=st.Users[sessions[strings.TrimPrefix(r.Header.Get("Authorization"),"Bearer ")]];return u,ok&&u.Active=="true"}
func main(){load();m:=http.NewServeMux();m.HandleFunc("/ready",func(w http.ResponseWriter,r *http.Request){write(w,200,map[string]string{"status":"ready"})});m.HandleFunc("/api/",api);m.Handle("/",http.FileServer(http.Dir("web")));http.ListenAndServe("127.0.0.1:8080",m)}
func api(w http.ResponseWriter,r *http.Request){mu.Lock();defer mu.Unlock();p:=r.URL.Path;if p=="/api/authenticate-user"{v:=read(r);for _,u:=range st.Users{if u.Username==fmt.Sprint(v["username"])&&u.Password==hash(fmt.Sprint(v["password"])){t:=uid();sessions[t]=u.ID;if u.ActiveRole==""&&len(u.Roles)>0{u.ActiveRole=u.Roles[0];st.Users[u.ID]=u;save()};write(w,200,map[string]interface{}{"data":map[string]interface{}{"sessionToken":t,"userId":u.ID,"roles":u.Roles,"activeRole":u.ActiveRole}});return}};fail(w,"401","unauthorized","invalid credentials");return};u,ok:=actor(r);if !ok{fail(w,"401","unauthorized","authentication required");return};if p=="/api/ui/bootstrap"{write(w,200,map[string]interface{}{"data":map[string]interface{}{"user":user(u),"serverTime":now(),"requesterSamples":[]interface{}{},"operations":ops()}});return};if r.Method=="GET"&&strings.HasPrefix(p,"/api/read-sample-state/"){id:=strings.TrimPrefix(p,"/api/read-sample-state/");s:=st.Samples[id];if s.ID==""{fail(w,"404","not_found","sample not found");return};write(w,200,map[string]interface{}{"data":sample(s)});return};v:=read(r);switch p{case "/api/check-serviceability":write(w,200,map[string]interface{}{"data":map[string]interface{}{"serviceable":true,"reason":"network_available","targetLaboratoryId":"","estimatedArrivalAt":v["deliveryDeadline"],"serviceabilityVersion":st.Version}});return;case "/api/read-serviceability-snapshot":write(w,200,map[string]interface{}{"data":map[string]interface{}{"version":st.Version,"status":"published","computedAt":now(),"networkRevision":st.Version,"regions":[]interface{}{},"activeCollectionPointCount":0}});return;case "/api/select-active-role":role:=fmt.Sprint(v["role"]);for _,x:=range u.Roles{if x==role{u.ActiveRole=role;st.Users[u.ID]=u;save();write(w,200,map[string]interface{}{"data":map[string]interface{}{"activeRole":role,"roles":u.Roles}});return}};fail(w,"403","forbidden","role not assigned");return;case "/api/create-collection-request","/api/ingest-presealed-sample":create(w,u,v,p);return;case "/api/read-sample-lifecycle":s:=st.Samples[fmt.Sprint(v["sampleId"])];write(w,200,map[string]interface{}{"data":map[string]interface{}{"sampleId":s.ID,"status":s.Status,"sealed":s.Status=="sealed","completedLegIds":[]string{},"activeReplacementPlanIds":[]string{},"timeline":s.Timeline,"locationStale":s.LocationStale}});return;case "/api/list-role-work":write(w,200,map[string]interface{}{"data":map[string]interface{}{"pending":[]interface{}{},"inProgress":[]interface{}{},"completed":[]interface{}{}}});return;case "/api/read-operations-state":write(w,200,map[string]interface{}{"data":ops()});return;case "/api/search-audit-trail":write(w,200,map[string]interface{}{"data":map[string]interface{}{"entries":st.Audits,"total":len(st.Audits),"returned":len(st.Audits),"offset":0,"limit":100,"order":"newest_first","hasMore":false}});return};mutation(w,u,p,v)}
