		write(w, 200, map[string]interface{}{"data": map[string]interface{}{"version": st.Version, "status": "published", "computedAt": now(), "networkRevision": st.Version, "regions": []interface{}{}, "activeCollectionPointCount": 0}})
		return
	case "/api/select-active-role":
		role := fmt.Sprint(v["role"])
		for _, x := range u.Roles {
			if x == role {
				u.ActiveRole = role
				st.Users[u.ID] = u
				save()
				write(w, 200, map[string]interface{}{"data": map[string]interface{}{"activeRole": role, "roles": u.Roles}})
				return
			}
		}
		fail(w, "403", "forbidden", "role not assigned")
		return
	case "/api/create-collection-request", "/api/ingest-presealed-sample":
		create(w, u, v, p)
		return
	case "/api/read-sample-lifecycle":
		s := st.Samples[fmt.Sprint(v["sampleId"])]
		write(w, 200, map[string]interface{}{"data": map[string]interface{}{"sampleId": s.ID, "status": s.Status, "sealed": s.Status == "sealed", "completedLegIds": []string{}, "activeReplacementPlanIds": []string{}, "timeline": s.Timeline, "locationStale": s.LocationStale}})
		return
	case "/api/list-role-work":
		write(w, 200, map[string]interface{}{"data": map[string]interface{}{"pending": []interface{}{}, "inProgress": []interface{}{}, "completed": []interface{}{}}})
		return
	case "/api/read-operations-state":
		write(w, 200, map[string]interface{}{"data": ops()})
		return
	case "/api/search-audit-trail":
		write(w, 200, map[string]interface{}{"data": map[string]interface{}{"entries": st.Audits, "total": len(st.Audits), "returned": len(st.Audits), "offset": 0, "limit": 100, "order": "newest_first", "hasMore": false}})
		return
	}
	mutation(w, u, p, v)
}
func user(u User) map[string]interface{} {
	return map[string]interface{}{"userId": u.ID, "username": u.Username, "email": "", "fullName": "", "phone": "", "roles": u.Roles, "qualifications": u.Qualifications, "certifications": []interface{}{}, "active": u.Active == "true"}
